(function(root){'use strict';
class KeyPool {
 constructor(){this.keys=[];this.projects=new Map();this.active=null;this.busy=false;this.counter=0;}
 save(storage){if(!this.keys.length){storage.removeItem('eilav.gemini.keys.v1');return;}storage.setItem('eilav.gemini.keys.v1',JSON.stringify({version:1,keys:this.keys,active:this.active,projects:[...this.projects]}));}
 restore(storage){const raw=storage.getItem('eilav.gemini.keys.v1');if(!raw)return;const data=JSON.parse(raw);if(data.version!==1||!Array.isArray(data.keys)||data.keys.length>20||!Array.isArray(data.projects))throw Error('저장된 키 목록을 읽을 수 없습니다.');const next=new KeyPool();for(const k of data.keys){const id=next.add(k.label,k.project,k.key);if(k.usage){const u=k.usage;for(const field of ['requests','responses','input','output','total'])next.keys.at(-1).usage[field]=Number.isSafeInteger(u[field])&&u[field]>=0?u[field]:0;}if(k.status==='invalid')next.keys.at(-1).status='invalid';if(k.id===data.active)next.active=id;}for(const [project,state]of data.projects){if(typeof project!=='string'||!Number.isFinite(state?.retryAt))throw Error('저장된 한도 정보를 읽을 수 없습니다.');next.projects.set(project,{retryAt:state.retryAt});}this.keys=next.keys;this.active=next.active;this.projects=next.projects;this.counter=next.counter;}
 add(label,project,key){label=label.trim();project=project.trim().toLowerCase();key=key.trim();if(!label||!project||!key)throw Error('키 이름, Google 프로젝트 ID, API 키를 입력해주세요.');if(label.length>60||!/^[a-z0-9][a-z0-9-]{2,62}$/.test(project))throw Error('실제 Google 프로젝트 ID를 입력해주세요. 영문 소문자·숫자·하이픈만 사용할 수 있습니다.');if(this.keys.length>=20)throw Error('최대 20개 키까지 등록할 수 있습니다.');if(this.keys.some(k=>k.key===key))throw Error('이미 등록한 API 키입니다.');const entry={id:++this.counter,label,project,key,status:'ready',usage:{requests:0,responses:0,input:0,output:0,total:0}};this.keys.push(entry);if(!this.active)this.active=entry.id;return entry.id;}
 remove(id){if(this.busy)throw Error('요청이 끝난 뒤 키를 삭제해주세요.');const entry=this.keys.find(k=>k.id===id);if(entry)entry.key='';this.keys=this.keys.filter(k=>k.id!==id);if(this.active===id)this.active=this.keys[0]?.id||null;}
 select(id){if(this.busy)throw Error('요청이 끝난 뒤 키를 바꿔주세요.');if(!this.keys.some(k=>k.id===id))throw Error('등록된 키를 선택해주세요.');this.active=id;}
 reset(project,now=Date.now()){const state=this.projects.get(project);if(state&&now<state.retryAt)throw Error('대기 시간이 지나지 않았습니다. 잠시 후 다시 시도해주세요.');this.projects.delete(project);for(const key of this.keys)if(key.project===project)key.status='ready';}
 async test(id,request){if(this.busy)throw Error('진행 중인 요청이 끝난 뒤 테스트해주세요.');const entry=this.keys.find(k=>k.id===id);if(!entry)throw Error('등록된 키를 선택해주세요.');const quota=this.projects.get(entry.project);if(quota&&Date.now()<quota.retryAt)throw Error('한도 초과 대기 시간이 지나지 않았습니다.');this.busy=true;try{entry.usage.requests++;const result=await request(entry.key);entry.status='ready';this.projects.delete(entry.project);return result;}catch(e){if(e.status===429)this.projects.set(entry.project,{retryAt:Date.now()+Math.max(60000,e.retryAfterMs||0)});if(e.status===401||e.status===403)entry.status='invalid';throw e;}finally{this.busy=false;}}
 recordUsage(key,metadata){const entry=this.keys.find(k=>k.key===key);if(!entry)return;entry.usage.responses++;for(const [field,source]of [["input","promptTokenCount"],["output","candidatesTokenCount"],["total","totalTokenCount"]]){const n=metadata[source];if(Number.isSafeInteger(n)&&n>=0)entry.usage[field]+=n;}}
 summary(){return this.keys.map(k=>({id:k.id,label:k.label,project:k.project,active:k.id===this.active,status:this.projects.has(k.project)?'quota':k.status,mask:'••••'+k.key.slice(-4),usage:{...k.usage}}));}
 async execute(request,{fallback=true,onSwitch=()=>{}}={}){if(this.busy)throw Error('이미 Gemini 요청을 처리하고 있습니다.');if(!this.keys.length)throw Error('Gemini API 키를 먼저 등록해주세요.');this.busy=true;const candidates=[...this.keys].sort((a,b)=>(b.id===this.active)-(a.id===this.active));const attempted=new Set();let lastError;try{for(const key of candidates){if(!fallback&&key.id!==this.active)continue;if(key.status==='invalid'||this.projects.has(key.project)||attempted.has(key.project))continue;attempted.add(key.project);onSwitch({label:key.label,project:key.project});try{key.usage.requests++;const value=await request(key.key);this.active=key.id;return value;}catch(error){lastError=error;if(error.status===429){this.projects.set(key.project,{retryAt:Date.now()+Math.max(60000,error.retryAfterMs||0)});if(!fallback)throw error;continue;}if(error.status===401||error.status===403){key.status='invalid';throw error;}throw error;}}throw lastError||Error('사용 가능한 프로젝트가 없습니다. Google AI Studio에서 한도를 확인한 후 중지를 해제해주세요.');}finally{this.busy=false;}}
}
if(typeof module!=='undefined'&&module.exports)module.exports=KeyPool;else root.DSKeyPool=KeyPool;
})(typeof window==='undefined'?globalThis:window);
